import { cloneElement, useEffect, useId, useState } from 'react';
import { Link } from 'react-router-dom';
import { externalApi } from '../../../lib/api.js';
import { SEO_FACTS, SEO_RECORDS, SEO_DRAFT_FIELDS } from '../../../../../server/src/common/vendorSeoContract.js';
import { Page, Card } from './shared.jsx';

const control = 'mt-1 w-full min-w-0 border border-gray-200 rounded-xl bg-white px-3 py-2 text-sm text-ink';
const button = 'min-h-11 rounded-xl border border-gray-200 px-4 py-2 text-sm font-semibold disabled:opacity-50';
const today = () => new Date().toISOString().slice(0, 10);
const tabs = [['overview', 'Overview'], ['evidence', 'Business evidence'], ['research', 'Research & audits'], ['content', 'Content drafts'], ['plan', '30 / 60 / 90 days'], ['reports', 'Reports']];
function Field({ label, children }) { const id = useId(); return <div className="min-w-0"><label htmlFor={id} className="block text-sm font-medium">{label}</label>{cloneElement(children, { id })}</div>; }
function Download({ onClick, disabled, children }) { return <button type="button" className={button} disabled={disabled} onClick={onClick}>{children}</button>; }
function saveJson(data, filename) {
  const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' }));
  const anchor = document.createElement('a'); anchor.href = url; anchor.download = filename; anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
}
export default function SeoGrowth() {
  const [data, setData] = useState(null), [workspace, setWorkspace] = useState(null), [dirty, setDirty] = useState(false);
  const [tab, setTab] = useState('overview'), [kind, setKind] = useState('research'), [editing, setEditing] = useState(null);
  const [busy, setBusy] = useState(false), [error, setError] = useState(''), [message, setMessage] = useState(''), [confirmed, setConfirmed] = useState(false);
  function accept(result) { setData(result); setWorkspace(result.workspace); setDirty(false); setConfirmed(false); }
  useEffect(() => { let live = true; externalApi.call('/vendor/seo').then(result => { if (live) accept(result); }).catch(e => { if (live) setError(e.data?.message || e.message); }); return () => { live = false; }; }, []);
  useEffect(() => { if (!dirty) return; const handler = event => { event.preventDefault(); event.returnValue = ''; }; window.addEventListener('beforeunload', handler); return () => window.removeEventListener('beforeunload', handler); }, [dirty]);
  useEffect(() => { if (editing) { const editor = document.getElementById('seo-record-editor'); editor?.scrollIntoView({ block: 'start' }); editor?.querySelector('input, select, textarea')?.focus({ preventScroll: true }); } }, [editing?.item.id]);
  function change(update) { setWorkspace(current => ({ ...current, ...update })); setDirty(true); setConfirmed(false); setMessage(''); }
  async function act(work) { setBusy(true); setError(''); setMessage(''); try { await work(); } catch (e) { setError(e.data?.message || e.message); } finally { setBusy(false); } }
  function persist() { return act(async () => { const { revision, evidence, records, draft } = workspace; accept(await externalApi.call('/vendor/seo', { method: 'PUT', body: { revision, evidence, records, draft } })); setMessage('Workspace saved. Any previous review has been cleared.'); }); }
  function editItem(group, item) { setEditing({ group, item: { ...item } }); }
  function newEvidence() { editItem('evidence', { id: crypto.randomUUID(), field: 'businessName', value: '', sourceUrl: '', observedAt: today(), identityConfirmed: false, publicUseApproved: false }); }
  function newRecord(selected = kind) { editItem('records', { id: crypto.randomUUID(), kind: selected, title: '', detail: '', sourceUrl: '', observedAt: today(), language: '', location: '', basis: 'NEEDS_DATA', target: 'STARVNT', period: selected === 'action' ? '30' : '', completed: false, metric: '', startDate: '', endDate: '' }); }
  function keepItem(event) { event.preventDefault(); const items = workspace[editing.group]; const exists = items.some(item => item.id === editing.item.id); change({ [editing.group]: exists ? items.map(item => item.id === editing.item.id ? editing.item : item) : [...items, editing.item] }); setEditing(null); }
  function itemChange(key, value) { setEditing(current => ({ ...current, item: { ...current.item, [key]: value } })); }
  function removeItem(group, id) { change({ [group]: workspace[group].filter(item => item.id !== id) }); if (editing?.item.id === id) setEditing(null); }
  const summary = data?.summary, profile = data?.profile;
  const workingRecords = workspace?.records || [];
  const filtered = workingRecords.filter(item => item.kind === kind);
  return <Page title="SEO & GEO growth" sub="Build a discoverable business with accurate information, useful content and recorded evidence." wide>
    {error && <Card><p role="alert" className="text-red-700 break-words">{error}</p><p className="text-sm text-muted mt-2">If a newer revision exists, download your unsaved copy before reloading this page.</p>{workspace && <Download onClick={() => saveJson(workspace, 'starvnt-seo-unsaved-copy.json')}>Download unsaved copy</Download>}</Card>}
    {message && <p role="status" className="text-sm text-primary">{message}</p>}
    {!data && !error && <Card><p role="status">Loading your SEO workspace…</p></Card>}
    {data && <fieldset disabled={busy} aria-label="SEO workspace" className="contents">
      <Card><div className="flex flex-wrap items-center gap-3"><div className="mr-auto min-w-0"><p className="font-bold break-words">{profile.businessName}</p><p className="text-xs text-muted mt-1">{profile.category || 'Category not provided'} · {profile.location || 'Location not provided'} · {summary.status.replaceAll('_', ' ')}</p></div><button className={`${button} bg-primary text-white`} disabled={busy || !dirty || Boolean(editing)} onClick={persist}>{busy ? 'Working…' : dirty ? 'Save workspace' : 'Saved'}</button></div><p className="text-xs text-muted mt-3">Private planning workspace. Saving or reviewing a draft does not publish it or modify Google, social accounts or your public profile. Readiness scores measure evidence completeness, not rankings.</p>{dirty && <p role="status" className="text-sm mt-2">You have unsaved changes. Save before switching to another Vendor OS page. Scores reflect the last saved version.</p>}</Card>
      <nav aria-label="SEO workspace sections" className="flex flex-wrap gap-2">{tabs.map(([id, label]) => <button type="button" key={id} aria-pressed={tab === id} disabled={Boolean(editing)} className={`${button} ${tab === id ? 'bg-primary text-white border-primary' : 'bg-white text-ink'}`} onClick={() => { setTab(id); setEditing(null); }}>{label}</button>)}</nav>
      {tab === 'overview' && <>
        <section aria-label="Evidence readiness" className="grid gap-4 sm:grid-cols-3">{[['SEO evidence', summary.seo], ['GEO evidence', summary.geo], ['Local SEO evidence', summary.local]].map(([label, score]) => <Card key={label} title={label}><p className="text-3xl font-bold text-primary">{score.percent}%</p><ul className="mt-3 space-y-2 text-sm">{score.checks.map(check => <li key={check.label}>{check.ready ? '✓' : '○'} {check.label}</li>)}</ul></Card>)}</section>
        <Card title="Next steps">{summary.blockers.length ? <ul className="list-disc pl-5 space-y-2 text-sm">{summary.blockers.map(blocker => <li key={blocker}>{blocker}</li>)}</ul> : <p className="text-sm">Core evidence is recorded. Review your research and content against the sources before marking the draft reviewed.</p>}<p className="mt-3 text-sm text-muted">{summary.scoreMeaning} Unconfirmed, unapproved or older than 180-day evidence entries: {summary.staleEvidence}.</p><button className={`${button} mt-3`} onClick={() => setTab('evidence')}>Review business evidence</button></Card>
        <Card title="Your saved profile"><dl className="grid gap-3 sm:grid-cols-2 text-sm">{[['Vendor ID', profile.vendorId], ['Business status', profile.status], ['Verification ladder', profile.verificationStatus], ['Profile completeness', `${summary.profileCompletion.percent}%`], ['Active services in audit window', profile.serviceCount], ['Portfolio items', profile.portfolioCount], ['Website', profile.website || 'NOT PROVIDED']].map(([label, value]) => <div key={label}><dt className="text-muted">{label}</dt><dd className="font-medium break-words">{value}</dd></div>)}</dl><p className="text-xs text-muted mt-3">Profile information is not automatically verified public evidence. {summary.profileCompletion.meaning} {profile.partial && 'Service / coverage inputs are limited to 100 records; this snapshot is partial.'}</p><div className="flex gap-4 mt-3 text-sm"><Link className="underline text-primary" to="/vendor/profile">Edit business profile</Link><Link className="underline text-primary" to="/vendor/services">Manage services</Link></div></Card>
        <Card title="All ten requirements areas">{summary.phases.map(phase => <details className="border-b border-gray-100 py-3" key={phase.id}><summary className="cursor-pointer text-sm font-semibold">{phase.title}</summary><ul className="list-disc pl-5 space-y-1 text-sm mt-3">{phase.checks.map(check => <li key={check}>{check}</li>)}</ul><p className="text-xs text-muted mt-3">{phase.records} saved related records. Record count does not certify that the phase is complete.</p><button className={`${button} mt-2`} onClick={() => { setKind(phase.kind); setTab('research'); }}>Open related research</button></details>)}</Card>
      </>}
      {tab === 'evidence' && <>
        <Card title="Facts allowed into draft suggestions"><p className="text-sm text-muted">Add a public source and its observation date. Confirm it belongs to your business and that you have the right to use the information publicly. This is your attestation, not independent STARVNT verification. Never enter private owner contacts, identity documents, bank details or customer information.</p><p className="text-sm mt-3">Saved profile: {profile.bio || 'Description NOT PROVIDED'}</p><ul className="text-sm mt-2 space-y-1">{profile.services.map((s, i) => <li key={i}>{s.name} · {s.category}</li>)}</ul><button className={`${button} mt-4`} disabled={busy || Boolean(editing)} onClick={newEvidence}>Add business evidence</button></Card>
        {workspace.evidence.map(item => <Card key={item.id}><p className="text-xs text-muted">{SEO_FACTS[item.field]} · {item.observedAt}</p><p className="font-semibold mt-1 break-words">{item.value}</p><p className="text-xs mt-2">{item.identityConfirmed ? 'Identity confirmed by vendor' : 'Identity needs confirmation'} · {item.publicUseApproved ? 'Public use allowed by vendor' : 'Public use not approved'}</p>{item.sourceUrl && <a href={item.sourceUrl} target="_blank" rel="noopener noreferrer" className="block text-primary underline text-sm mt-2 break-all">View evidence source</a>}<div className="flex flex-wrap gap-2 mt-3"><button className={button} disabled={busy} onClick={() => editItem('evidence', item)}>Edit evidence</button><button className={button} disabled={busy} onClick={() => removeItem('evidence', item.id)}>Remove from workspace</button></div></Card>)}
        {!workspace.evidence.length && <Card>No evidence saved. Start with business name, category, services and actual service locations.</Card>}
      </>}
      {tab === 'research' && <>
        <Card title="Research ledger"><Field label="Research area"><select className={control} value={kind} onChange={event => { setKind(event.target.value); setEditing(null); }}>{Object.entries(SEO_RECORDS).map(([id, label]) => <option value={id} key={id}>{label}</option>)}</select></Field><p className="text-sm text-muted mt-3">Record source URLs and dates. Keep observations, estimates and recommendations separate. A similar business name alone does not verify ownership. Competitors should share real services and locations; aim for 5–10 where sufficient evidence exists.</p><button className={`${button} mt-3`} disabled={busy || Boolean(editing)} onClick={() => newRecord()}>Add {SEO_RECORDS[kind].toLowerCase()}</button></Card>
        {filtered.map(item => <ResearchCard key={item.id} item={item} onEdit={() => editItem('records', item)} onRemove={() => removeItem('records', item.id)} busy={busy} />)}
        {!filtered.length && <Card><p className="text-sm">NEEDS DATA — no research saved in this area yet.</p></Card>}
      </>}
      {tab === 'content' && <>
        <Card title="Evidence-based content drafts"><p className="text-sm text-muted">Draft suggestions use current public-use evidence for your business. They do not invent keywords, FAQ answers, project details, reviews or credentials. Add researched service copy, FAQs and image descriptions below. Validate structured data against the visible page before any future publication.</p><button className={`${button} mt-3`} disabled={busy || dirty || Boolean(editing)} onClick={() => act(async () => { const result = await externalApi.call('/vendor/seo/generate', { method: 'POST', body: { revision: workspace.revision } }); change({ draft: result.draft }); setMessage('A basic proposal replaced the local draft. Review and save it; nothing was published.'); })}>Replace draft from saved evidence</button><p className="text-xs text-muted mt-2">Template-based suggestions; no AI provider is called. Missing facts remain blank.</p></Card>
        <Card><div className="grid gap-5">{Object.entries(SEO_DRAFT_FIELDS).map(([key, label]) => <Field key={key} label={label}>{['title', 'metaDescription', 'h1', 'canonical'].includes(key) ? <input className={control} type={key === 'canonical' ? 'url' : 'text'} maxLength={key === 'title' ? 120 : key === 'metaDescription' ? 320 : key === 'canonical' ? 1500 : 12000} value={workspace.draft[key] || ''} onChange={e => change({ draft: { ...workspace.draft, [key]: e.target.value } })} /> : <textarea className={`${control} ${key === 'structuredData' ? 'font-mono' : ''}`} rows={key === 'structuredData' ? 8 : 4} maxLength={12000} value={workspace.draft[key] || ''} onChange={e => change({ draft: { ...workspace.draft, [key]: e.target.value } })} />}</Field>)}</div></Card>
        <Card title="Human review"><p className="text-sm">{summary.reviewed ? `Saved draft reviewed on ${new Date(summary.reviewedAt).toLocaleDateString()}.` : 'The saved draft still needs review.'} Editing evidence, research or content clears the review. Changed business data or stale evidence can invalidate it.</p><label className="flex items-start gap-3 text-sm mt-4"><input className="mt-1" type="checkbox" checked={confirmed} onChange={e => setConfirmed(e.target.checked)} disabled={dirty || busy} /><span>I checked each claim against the source, confirmed public-use rights, and removed private information and unsupported claims.</span></label><button className={`${button} mt-3`} disabled={busy || dirty || !confirmed || Boolean(summary.blockers.length)} onClick={() => act(async () => { accept(await externalApi.call('/vendor/seo/review', { method: 'POST', body: { revision: workspace.revision, fingerprint: summary.fingerprint, confirmed: true } })); setMessage('Private draft marked reviewed. Public publishing remains a separate step.'); })}>Mark saved draft reviewed</button></Card>
      </>}
      {tab === 'plan' && <>
        <Card title="Execution roadmap"><p className="text-sm text-muted">Create tasks with an owner or dependency, evidence needed and a measurable outcome. Suggested sequence: verify business and analytics in 30 days; complete and review original content by 60 days; measure enquiries and paid bookings by 90 days. These are planning milestones, not promised results.</p><button className={`${button} mt-3`} disabled={busy || Boolean(editing)} onClick={() => newRecord('action')}>Add action</button></Card>
        <div className="grid gap-4 xl:grid-cols-3">{['30', '60', '90'].map(period => <Card key={period} title={`First ${period} days`}><div className="space-y-3">{workingRecords.filter(item => item.kind === 'action' && item.period === period).map(item => <div key={item.id} className="rounded-xl border border-gray-200 p-3 text-sm"><p className="font-semibold break-words">{item.completed ? '✓ ' : '○ '}{item.title}</p><p className="whitespace-pre-wrap break-words mt-2">{item.detail}</p><button className={`${button} mt-3`} disabled={busy} onClick={() => editItem('records', item)}>Edit action</button></div>)}{!workingRecords.some(item => item.kind === 'action' && item.period === period) && <p className="text-sm text-muted">No actions assigned yet.</p>}</div></Card>)}</div>
      </>}
      {tab === 'reports' && <>
        <Card title="Your 20-part growth pack"><p className="text-sm text-muted">Coverage of the last saved workspace. Recorded material still needs source and quality review; a scorecard does not mean the underlying research is finished.</p><ol className="grid gap-3 sm:grid-cols-2 mt-4">{data.growthPack.map((section, index) => <li className="rounded-xl border border-gray-200 p-3 text-sm" key={section.id}><p className="font-semibold">{index + 1}. {section.title}</p><p className="text-xs text-muted mt-1">{section.status === 'NEEDS_DATA' ? 'NEEDS DATA' : 'Recorded — requires review'}</p></li>)}</ol></Card>
        <Card title="Measurement sources"><p className="text-sm">{summary.measurements.message}</p><div className="grid gap-3 sm:grid-cols-3 mt-4">{['Indexed pages', 'Organic impressions / clicks / CTR', 'Attributed enquiries / qualified leads / paid bookings'].map(label => <div className="rounded-xl border border-gray-200 p-3" key={label}><p className="text-xs text-muted">{label}</p><p className="text-sm font-semibold mt-2">NOT CONNECTED</p></div>)}</div><p className="text-xs text-muted mt-3">Use authorized Search Console, Analytics and verified CRM data. Record period, source, deduplication and attribution limits. Do not treat missing data as zero or readiness as a search ranking. This view covers your vendor only; it is not a platform-wide CEO dashboard.</p><button className={`${button} mt-3`} disabled={busy || Boolean(editing)} onClick={() => { setKind('measurement'); setTab('research'); newRecord('measurement'); }}>Record sourced measurement</button></Card>
        {workingRecords.filter(item => item.kind === 'measurement').map(item => <ResearchCard key={item.id} item={item} busy={busy} onEdit={() => editItem('records', item)} onRemove={() => removeItem('records', item.id)} />)}
        <Card title="Export growth pack"><p className="text-sm text-muted">Export the current saved profile audit, evidence, scorecards, research, content drafts, action plans and sourced measurements. Sections without research remain incomplete. The export is private; check permissions before sharing.</p><div className="flex flex-wrap gap-3 mt-3"><Download disabled={busy || dirty || Boolean(editing)} onClick={() => act(async () => saveJson(await externalApi.call('/vendor/seo/export'), 'starvnt-seo-geo-growth-pack.json'))}>Download saved growth pack</Download><Download onClick={() => saveJson(workspace, 'starvnt-seo-workspace-backup.json')}>Download local workspace copy</Download></div></Card>
        <Card title="Review history"><ul className="space-y-2 text-sm">{workspace.history.slice().reverse().map((item, i) => <li key={i}>Revision {item.revision} · {item.action.replaceAll('_', ' ')} · {new Date(item.at).toLocaleString()}</li>)}</ul>{!workspace.history.length && <p className="text-sm text-muted">No saved changes yet.</p>}</Card>
      </>}
      {editing && <Card id="seo-record-editor" title={editing.group === 'evidence' ? 'Edit business evidence' : 'Edit research record'}><form onSubmit={keepItem} className="space-y-4">
        {editing.group === 'evidence' ? <>
          <Field label="Business fact"><select className={control} value={editing.item.field} onChange={e => itemChange('field', e.target.value)}>{Object.entries(SEO_FACTS).map(([id, label]) => <option value={id} key={id}>{label}</option>)}</select></Field>
          <Field label="Evidence value"><textarea required className={control} rows={3} maxLength={2000} value={editing.item.value} onChange={e => itemChange('value', e.target.value)} /></Field>
        </> : <>
          <p className="text-sm text-primary font-semibold">{SEO_RECORDS[editing.item.kind]}</p>
          <Field label="Title / search query / task"><input required className={control} maxLength={180} value={editing.item.title} onChange={e => itemChange('title', e.target.value)} /></Field>
          <Field label="Finding, comparison or recommendation"><textarea className={control} rows={5} maxLength={8000} value={editing.item.detail} onChange={e => itemChange('detail', e.target.value)} /></Field>
          <div className="grid gap-4 sm:grid-cols-2"><Field label="Evidence basis"><select className={control} value={editing.item.basis} onChange={e => itemChange('basis', e.target.value)}>{['NEEDS_DATA', 'OBSERVATION', 'ESTIMATE', 'RECOMMENDATION'].map(value => <option key={value} value={value}>{value.replaceAll('_', ' ')}</option>)}</select></Field><Field label="Where the issue belongs"><select className={control} value={editing.item.target} onChange={e => itemChange('target', e.target.value)}>{['STARVNT', 'VENDOR_WEBSITE', 'EXTERNAL_PROFILE'].map(value => <option key={value} value={value}>{value.replaceAll('_', ' ')}</option>)}</select></Field><Field label="Language"><select className={control} value={editing.item.language} onChange={e => itemChange('language', e.target.value)}>{[['', 'Not specified'], ['en', 'English'], ['bn', 'Bengali'], ['hi', 'Hindi'], ['other', 'Other']].map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select></Field><Field label="Relevant location"><input className={control} maxLength={200} value={editing.item.location} onChange={e => itemChange('location', e.target.value)} /></Field></div>
          {editing.item.kind === 'action' && <><Field label="Roadmap period"><select className={control} value={editing.item.period} onChange={e => itemChange('period', e.target.value)}>{['30', '60', '90'].map(value => <option key={value} value={value}>{value} days</option>)}</select></Field><label className="flex gap-3 text-sm"><input type="checkbox" checked={editing.item.completed} onChange={e => itemChange('completed', e.target.checked)} />Action completed</label></>}
          {editing.item.kind === 'measurement' && <div className="grid gap-4 sm:grid-cols-2"><Field label="Metric name"><input className={control} maxLength={100} value={editing.item.metric} onChange={e => itemChange('metric', e.target.value)} /></Field><Field label="Measured value (blank when unavailable)"><input className={control} type="number" min="0" max="1000000000000" step="any" value={editing.item.value ?? ''} onChange={e => itemChange('value', e.target.value === '' ? undefined : Number(e.target.value))} /></Field><Field label="Period start"><input type="date" max={today()} className={control} value={editing.item.startDate} onChange={e => itemChange('startDate', e.target.value)} /></Field><Field label="Period end"><input type="date" max={today()} className={control} value={editing.item.endDate} onChange={e => itemChange('endDate', e.target.value)} /></Field></div>}
        </>}
        <div className="grid gap-4 sm:grid-cols-2"><Field label="Public source URL"><input type="url" placeholder="https://" className={control} maxLength={1500} value={editing.item.sourceUrl} onChange={e => itemChange('sourceUrl', e.target.value)} /></Field><Field label="Observation / research date"><input required type="date" max={today()} className={control} value={editing.item.observedAt} onChange={e => itemChange('observedAt', e.target.value)} /></Field></div>
        {editing.group === 'evidence' && <><label className="flex gap-3 items-start text-sm"><input className="mt-1" type="checkbox" checked={editing.item.identityConfirmed} onChange={e => itemChange('identityConfirmed', e.target.checked)} />I confirm this source and information belong to my business.</label><label className="flex gap-3 items-start text-sm"><input className="mt-1" type="checkbox" checked={editing.item.publicUseApproved} onChange={e => itemChange('publicUseApproved', e.target.checked)} />I authorize using this fact in public-content drafts and confirm the necessary rights.</label></>}
        <div className="flex flex-wrap gap-3"><button className={`${button} bg-primary text-white`} type="submit">Keep in workspace</button><button className={button} type="button" onClick={() => setEditing(null)}>Cancel edit</button></div><p className="text-xs text-muted">Then use Save workspace to persist your changes.</p>
      </form></Card>}
      <Card title="Source guidance"><ul className="space-y-2 text-sm">{summary.guidance.map(source => <li key={source.url}><a className="text-primary underline" href={source.url} target="_blank" rel="noopener noreferrer">{source.title}</a></li>)}</ul><p className="text-xs text-muted mt-3">Accurate, useful public information supports discovery. Neither Google rankings nor AI recommendations are guaranteed.</p></Card>
    </fieldset>}
  </Page>;
}
function ResearchCard({ item, onEdit, onRemove, busy }) {
  return <Card><p className="text-xs text-muted">{item.basis.replaceAll('_', ' ')} · {item.observedAt} · {item.target.replaceAll('_', ' ')}{item.language ? ` · ${item.language}` : ''}{item.location ? ` · ${item.location}` : ''}</p><h2 className="font-bold mt-2 break-words">{item.title}</h2><p className="text-sm whitespace-pre-wrap break-words mt-2">{item.detail}</p>{item.kind === 'measurement' && <p className="text-sm mt-2">{item.metric || 'Metric not specified'}: {item.value ?? 'NOT PROVIDED'} · {item.startDate || '?'} to {item.endDate || '?'}</p>}{item.sourceUrl && <a className="inline-block text-primary underline text-sm mt-3 break-all" href={item.sourceUrl} target="_blank" rel="noopener noreferrer">View research source</a>}<div className="flex flex-wrap gap-3 mt-3"><button className={button} disabled={busy} onClick={onEdit}>Edit record</button><button className={button} disabled={busy} onClick={onRemove}>Remove from workspace</button></div></Card>;
}
